t.script:
document.addEventListener("DOMContentLoaded", function() {
    document.body.addEventListener("click", function(e) {
        let target = e.target.closest('a');
        if (target && target.getAttribute('href') && target.getAttribute('href').startsWith('/my/notifications/read')) {
            // Skip the specific button handled in portal_my_notifications
            if (target.id === 'btn_mark_all_read') return;

            e.preventDefault();
            let formData = new FormData();
            if (typeof odoo !== 'undefined' && odoo.csrf_token) {
                formData.append('csrf_token', odoo.csrf_token);
            }
            fetch(target.getAttribute('href'), { method: 'POST', body: formData }).then(response => {
                if (response.redirected) {
                    window.location.href = response.url;
                } else {
                    window.location.reload();
                }
            }).catch(() => {
                window.location.reload();
            });
        }
    });
});

div.script:
document.addEventListener("DOMContentLoaded", function() {
    const btnMarkRead = document.getElementById('btn_mark_all_read');
    if (btnMarkRead) {
        btnMarkRead.addEventListener('click', function(e) {
            e.preventDefault();
            let formData = new FormData();
            if (typeof odoo !== 'undefined' && odoo.csrf_token) {
                formData.append('csrf_token', odoo.csrf_token);
            }
            fetch(btnMarkRead.getAttribute('href'), {
                method: 'POST',
                body: formData
            }).then(() => {
                // Remove header bell badges
                const badges = document.querySelectorAll('.fa-bell + .badge');
                badges.forEach(b => b.remove());
                // Also remove from dropdown if present
                const dropdownReadLink = document.querySelector('a[href="/my/notifications/read_all"]');
                if (dropdownReadLink) {
                    if (dropdownReadLink.id !== 'btn_mark_all_read') {
                        dropdownReadLink.remove();
                    }
                }

                // Update notification cards in the list
                const unreadCards = document.querySelectorAll('.bg-white.border-primary-subtle');
                unreadCards.forEach(c => {
                    c.classList.remove('bg-white', 'border-primary-subtle');
                    c.classList.add('bg-light', 'border-light');

                    // Remove 'Nouveau' badge
                    const newBadge = c.querySelector('.badge.bg-danger');
                    if (newBadge) newBadge.remove();

                    // Make title text-muted
                    const title = c.querySelector('h6.text-dark');
                    if (title) {
                        title.classList.remove('text-dark');
                        title.classList.add('text-muted');
                    }
                });

                // Hide the mark all read button
                btnMarkRead.remove();
            });
        });
    }
});
